using Microsoft.EntityFrameworkCore;

// Cosmos DB context demonstrating two EF Core 9 breaking changes:
// 1. Discriminator property renamed from "Discriminator" to "$type"
// 2. Synchronous Cosmos DB queries removed — must use async
class CosmosContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "MyDatabase");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change: EF Core 9 Cosmos provider uses "$type" by default.
        // Existing documents still store "Discriminator", so remap to preserve
        // compatibility with pre-9.0 data.
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");
    }

    // Breaking change: Synchronous Cosmos queries (e.g. .ToList(), .First())
    // throw InvalidOperationException in EF Core 9.
    // All queries must use async equivalents.
    public async Task<List<Product>> GetExpensiveProductsAsync(decimal minPrice)
    {
        // BEFORE (EF Core 8 — no longer compiles/runs with Cosmos provider):
        //   return Products.Where(p => p.Price > minPrice).ToList();
        //
        // AFTER:
        return await Products
            .Where(p => p.Price > minPrice)
            .ToListAsync();
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public decimal Price { get; set; }
}

